/* ============================================================
   HRD Cost Breakdown - Team2 schema
   Source: HRD - Cost Breakdown (Dummy Data).xlsx
   Sheets: BUDGET-22-25 SSD, BUDGET-22-25 HRS & CIG, BUDGET-22-25 ATPD
   ============================================================ */

USE COSTANALYSER;
GO

IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = 'Team2')
    EXEC('CREATE SCHEMA Team2');
GO

-- Drop tables if re-running during development
IF OBJECT_ID('Team2.FactBudget','U') IS NOT NULL DROP TABLE Team2.FactBudget;
IF OBJECT_ID('Team2.GLDescription','U') IS NOT NULL DROP TABLE Team2.GLDescription;
IF OBJECT_ID('Team2.CostCenter','U') IS NOT NULL DROP TABLE Team2.CostCenter;
IF OBJECT_ID('Team2.BusinessUnit','U') IS NOT NULL DROP TABLE Team2.BusinessUnit;
GO

CREATE TABLE Team2.BusinessUnit (
    business_unit_id   INT             NOT NULL PRIMARY KEY,
    business_unit_code VARCHAR(20)     NOT NULL UNIQUE,
    business_unit_name VARCHAR(100)    NOT NULL
);
GO

CREATE TABLE Team2.CostCenter (
    cost_center_id     INT             NOT NULL PRIMARY KEY,
    business_unit_id   INT             NOT NULL
                        FOREIGN KEY REFERENCES Team2.BusinessUnit(business_unit_id),
    cost_center_name   VARCHAR(150)    NOT NULL,
    display_order      INT             NOT NULL,
    CONSTRAINT UQ_CostCenter UNIQUE (business_unit_id, cost_center_name)
);
GO

CREATE TABLE Team2.GLDescription (
    gl_description_id  INT             NOT NULL PRIMARY KEY,
    description         VARCHAR(150)   NOT NULL UNIQUE,
    measure_type         VARCHAR(10)   NOT NULL CHECK (measure_type IN ('Cost','Headcount')),
    is_subtotal          BIT           NOT NULL DEFAULT 0,
    display_order         INT          NOT NULL
);
GO

CREATE TABLE Team2.FactBudget (
    fact_id             BIGINT         IDENTITY(1,1) PRIMARY KEY,
    cost_center_id       INT           NOT NULL
                          FOREIGN KEY REFERENCES Team2.CostCenter(cost_center_id),
    gl_description_id     INT          NOT NULL
                          FOREIGN KEY REFERENCES Team2.GLDescription(gl_description_id),
    fiscal_year            SMALLINT    NOT NULL CHECK (fiscal_year BETWEEN 2000 AND 2100),
    value_type              VARCHAR(10) NOT NULL DEFAULT 'Actual'
                          CHECK (value_type IN ('Actual','Plan')),
    amount                    DECIMAL(18,2) NULL,
    source_sheet                VARCHAR(100) NULL,
    CONSTRAINT UQ_FactBudget UNIQUE (cost_center_id, gl_description_id, fiscal_year, value_type)
);
GO

